BEGIN;

-- 1. Thêm danh mục (Categories)
ON CONFLICT (slug) 
DO UPDATE SET name = EXCLUDED.name, sort_order = EXCLUDED.sort_order, is_active = true;

-- 2. Thêm thương hiệu (Brands)
ON CONFLICT (slug) 
DO UPDATE SET name = EXCLUDED.name;

-- 3. Bảng tạm chứa dữ liệu seed sản phẩm
CREATE TEMP TABLE seed_products (
    slug VARCHAR(220) PRIMARY KEY,
    category_slug VARCHAR(140) NOT NULL,
    brand_slug VARCHAR(140),
    name VARCHAR(255) NOT NULL,
    short_description VARCHAR(500),
    description TEXT,
    price NUMERIC(13,2) NOT NULL,
    sale_price NUMERIC(13,2),
    stock_quantity INT NOT NULL,
    specifications JSONB,
    main_image VARCHAR(1000),
    is_featured BOOLEAN NOT NULL
) ON COMMIT DROP;


-- 4. Chèn dữ liệu vào bảng products
SELECT c.id, b.id, seed.slug, seed.name, seed.short_description, seed.description, seed.price, seed.sale_price, seed.stock_quantity, seed.specifications, seed.main_image, seed.is_featured
FROM seed_products seed
JOIN categories c ON c.slug = seed.category_slug
LEFT JOIN brands b ON b.slug = seed.brand_slug
ON CONFLICT (slug) DO NOTHING;

-- 5. Thêm hình ảnh sản phẩm (Product Images)
SELECT p.id, p.main_image, p.name, 0
FROM products p
JOIN seed_products seed ON seed.slug = p.slug
WHERE p.main_image IS NOT NULL
ON CONFLICT DO NOTHING;

-- 6. Thêm biến thể sản phẩm (Product Variants)
SELECT id, 'IPHONE16PM-256-NAT', 'Titan tự nhiên', '256GB', 0, 8 FROM products WHERE slug = 'iphone-16-pro-max'
ON CONFLICT (sku) DO NOTHING;

SELECT id, 'IPHONE16PM-256-BLK', 'Titan đen', '256GB', 0, 6 FROM products WHERE slug = 'iphone-16-pro-max'
ON CONFLICT (sku) DO NOTHING;

SELECT id, 'S25U-256-TITANIUM', 'Titanium Gray', '256GB', 0, 9 FROM products WHERE slug = 'samsung-galaxy-s25-ultra'
ON CONFLICT (sku) DO NOTHING;

COMMIT;